# PATCH-009-Framework-Migration.ps1
# CodeForge 3.0 migration: plain PHP -> SvelteKit + Laravel 11 + MySQL
#
# Default behavior:
#   1. archives the current plain-PHP source
#   2. installs the framework code
#   3. preserves the existing MySQL database
#   4. runs source regression tests
#   5. runs Composer/npm setup, migrations, compiler checks and production build
#
# Usage:
#   cd D:\xampp\htdocs\codeforge
#   powershell -ExecutionPolicy Bypass -File .\PATCH-009-Framework-Migration.ps1
#
# Optional:
#   -SkipSetup       install source only; run setup-codeforge.ps1 later
#   -DbPort 3306     force MySQL port (otherwise auto-detects 3307/3306)

param(
    [switch]$SkipSetup,
    [int]$DbPort = 0
)

$ErrorActionPreference = 'Stop'

function Step([string]$message) {
    Write-Host ''
    Write-Host "==> $message" -ForegroundColor Cyan
}

function Ok([string]$message) {
    Write-Host "[OK]   $message" -ForegroundColor Green
}

function Warn([string]$message) {
    Write-Host "[WARN] $message" -ForegroundColor Yellow
}

$root = Split-Path -Parent $MyInvocation.MyCommand.Path
if (-not $root) { $root = (Get-Location).Path }
Set-Location $root

$scriptName = Split-Path -Leaf $MyInvocation.MyCommand.Path
$stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$backupRoot = Join-Path $root "patch-backups\PATCH-009-$stamp"
New-Item -ItemType Directory -Force -Path $backupRoot | Out-Null

$isFramework = (Test-Path (Join-Path $root 'backend\composer.json')) -and
               (Test-Path (Join-Path $root 'frontend\package.json'))

$isPlain = Test-Path (Join-Path $root 'core\bootstrap.php')
if (-not $isFramework -and -not $isPlain) {
    throw 'This does not look like the CodeForge project root. Run the patch from D:\xampp\htdocs\codeforge.'
}

Step 'Backing up the current CodeForge source'

$backupSource = Join-Path $backupRoot 'source-before-framework-migration'
New-Item -ItemType Directory -Force -Path $backupSource | Out-Null

$excludedNames = @(
    'patch-backups',
    $scriptName
)

$currentEntries = Get-ChildItem -Path $root -Force | Where-Object {
    $excludedNames -notcontains $_.Name
}

foreach ($entry in $currentEntries) {
    Copy-Item $entry.FullName (Join-Path $backupSource $entry.Name) -Recurse -Force
}
Ok "Backup created at $backupSource"

$legacyDir = $null

if (-not $isFramework) {
    Step 'Archiving the plain-PHP application'

    $legacyDir = Join-Path $root "legacy-plain-php-$stamp"
    New-Item -ItemType Directory -Force -Path $legacyDir | Out-Null

    # Capture the list before moving anything so the new legacy directory is never moved into itself.
    $toArchive = Get-ChildItem -Path $root -Force | Where-Object {
        $_.Name -ne 'patch-backups' -and
        $_.Name -ne $scriptName -and
        $_.FullName -ne $legacyDir
    }

    foreach ($entry in $toArchive) {
        Move-Item $entry.FullName (Join-Path $legacyDir $entry.Name) -Force
    }

    Ok "Plain-PHP source archived at $legacyDir"
} else {
    Step 'Existing framework tree detected'
    Ok 'PATCH-009 will refresh the framework source in place.'
}

Step 'Reconstructing the audited framework package'

