'@

$tempZip = Join-Path $env:TEMP "codeforge-framework-$stamp.zip"
$tempExtract = Join-Path $env:TEMP "codeforge-framework-$stamp"

[System.IO.File]::WriteAllBytes(
    $tempZip,
    [Convert]::FromBase64String(($packageBase64 -replace '\s', ''))
)

$actualHash = (Get-FileHash -Path $tempZip -Algorithm SHA256).Hash.ToLowerInvariant()
$expectedHash = '57eab33d18184b95b7af6546ab1ea8c141abf9c1d94c3521f564adf6e2fd75da'

if ($actualHash -ne $expectedHash) {
    Remove-Item $tempZip -Force -ErrorAction SilentlyContinue
    throw "Embedded framework package failed SHA-256 verification. Expected $expectedHash but got $actualHash."
}
Ok "Framework package integrity verified: $actualHash"

if (Test-Path $tempExtract) {
    Remove-Item $tempExtract -Recurse -Force
}
New-Item -ItemType Directory -Force -Path $tempExtract | Out-Null
Expand-Archive -Path $tempZip -DestinationPath $tempExtract -Force

Step 'Installing SvelteKit + Laravel source'

Get-ChildItem -Path $tempExtract -Force | ForEach-Object {
    Copy-Item $_.FullName (Join-Path $root $_.Name) -Recurse -Force
}

Remove-Item $tempZip -Force -ErrorAction SilentlyContinue
Remove-Item $tempExtract -Recurse -Force -ErrorAction SilentlyContinue

if (-not (Test-Path (Join-Path $root 'backend\composer.json'))) {
    throw 'Framework installation verification failed: backend/composer.json is missing.'
}
if (-not (Test-Path (Join-Path $root 'frontend\package.json'))) {
    throw 'Framework installation verification failed: frontend/package.json is missing.'
}

Ok 'Laravel 11 backend installed'
Ok 'SvelteKit/Svelte 5 frontend installed'
Ok 'Existing MySQL project database has not been reset or deleted'

Step 'Running dependency-free source regression checks'

$php = 'D:\xampp\php\php.exe'
if (-not (Test-Path $php)) {
    $phpCommand = Get-Command php -ErrorAction SilentlyContinue
    if ($null -eq $phpCommand) {
        throw 'PHP was not found. XAMPP PHP 8.2+ is required.'
    }
    $php = $phpCommand.Source
}

$lintFailed = $false
$oldPreference = $ErrorActionPreference
$ErrorActionPreference = 'Continue'

Get-ChildItem -Path (Join-Path $root 'backend') -Recurse -File -Filter '*.php' | ForEach-Object {
    $lint = & $php -l $_.FullName 2>&1
    if ($LASTEXITCODE -ne 0) {
        Write-Host "[FAIL] $($_.FullName)" -ForegroundColor Red
        $lint | ForEach-Object { Write-Host $_ }
        $lintFailed = $true
    }
}

$rootIndex = Join-Path $root 'index.php'
if (Test-Path $rootIndex) {
    $lint = & $php -l $rootIndex 2>&1
    if ($LASTEXITCODE -ne 0) {
        Write-Host '[FAIL] index.php' -ForegroundColor Red
        $lint | ForEach-Object { Write-Host $_ }
        $lintFailed = $true
    }
}

$ErrorActionPreference = $oldPreference

if ($lintFailed) {
    throw 'PHP syntax validation failed. Your pre-migration source backup is preserved under patch-backups.'
}
Ok 'All framework PHP files passed syntax validation'

& $php (Join-Path $root 'backend\tools\contract_test.php')
if ($LASTEXITCODE -ne 0) {
    throw 'Backend regression tests failed. Your pre-migration source backup is preserved under patch-backups.'
}
Ok '43 backend contract checks passed'

$nodeCommand = Get-Command node -ErrorAction SilentlyContinue
if ($null -ne $nodeCommand) {
    Push-Location (Join-Path $root 'frontend')
    & $nodeCommand.Source 'tools\contract-test.mjs'
    $frontendResult = $LASTEXITCODE
    Pop-Location

    if ($frontendResult -ne 0) {
        throw 'Frontend contract checks failed. Your pre-migration source backup is preserved under patch-backups.'
    }
    Ok '27 frontend contract checks passed'
} else {
    Warn 'Node.js was not found yet, so frontend contract checks will run during setup after Node is installed.'
}

Step 'Framework source migration complete'

Write-Host 'The old PHP application is no longer the active implementation.' -ForegroundColor White
if ($legacyDir) {
    Write-Host "Legacy source archive: $legacyDir" -ForegroundColor DarkGray
}
Write-Host "Full pre-migration backup: $backupSource" -ForegroundColor DarkGray
Write-Host ''
Write-Host 'Database policy:' -ForegroundColor Cyan
Write-Host '  - existing CodeForge tables/data are preserved'
Write-Host '  - Laravel support tables are added non-destructively'
Write-Host '  - missing optimization indexes are added idempotently'

if ($SkipSetup) {
    Write-Host ''
    Warn 'Dependency installation was skipped by request.'
    Write-Host 'Run this when ready:' -ForegroundColor White
    if ($DbPort -gt 0) {
        Write-Host "  powershell -ExecutionPolicy Bypass -File .\setup-codeforge.ps1 -DbPort $DbPort" -ForegroundColor Yellow
    } else {
        Write-Host '  powershell -ExecutionPolicy Bypass -File .\setup-codeforge.ps1' -ForegroundColor Yellow
    }
    exit 0
}

Step 'Installing dependencies, migrating MySQL and compiling SvelteKit'

$setupScript = Join-Path $root 'setup-codeforge.ps1'
if ($DbPort -gt 0) {
    & powershell -ExecutionPolicy Bypass -File $setupScript -DbPort $DbPort
} else {
    & powershell -ExecutionPolicy Bypass -File $setupScript
}

if ($LASTEXITCODE -ne 0) {
    Write-Host ''
    Warn 'Framework SOURCE migration succeeded, but environment setup did not finish.'
    Write-Host 'Do not restore the old source just because Composer/npm/MySQL setup failed.' -ForegroundColor White
    Write-Host 'Fix the prerequisite/connection error printed above, then rerun:' -ForegroundColor White
    if ($DbPort -gt 0) {
        Write-Host "  powershell -ExecutionPolicy Bypass -File .\setup-codeforge.ps1 -DbPort $DbPort" -ForegroundColor Yellow
    } else {
        Write-Host '  powershell -ExecutionPolicy Bypass -File .\setup-codeforge.ps1' -ForegroundColor Yellow
    }
    exit 2
}

Step 'PATCH-009 complete'

Write-Host 'PATCH-009 FRAMEWORK MIGRATION COMPLETED SUCCESSFULLY' -ForegroundColor Green
Write-Host ''
Write-Host 'Frontend: http://localhost:5173' -ForegroundColor Cyan
Write-Host 'Backend:  http://localhost:8000' -ForegroundColor Cyan
Write-Host 'XAMPP bridge: http://localhost/codeforge/' -ForegroundColor Cyan
Write-Host ''
Write-Host 'Start CodeForge:' -ForegroundColor White
Write-Host '  powershell -ExecutionPolicy Bypass -File .\start-codeforge.ps1' -ForegroundColor Yellow
Write-Host ''
Write-Host 'Full verification:' -ForegroundColor White
Write-Host '  powershell -ExecutionPolicy Bypass -File .\verify-codeforge.ps1 -FullBuild' -ForegroundColor Yellow
